'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = data[0];
const M = data[1];
const sums = new Array(M).fill(0);

let index = 2;
for (let i = 0; i < N; i++) {
  for (let j = 0; j < M; j++) {
    sums[j] += data[index++];
  }
}

console.log(Math.min(...sums));
